var e={preflight:{intro:{t:0,b:{t:2,i:[{t:3}],s:`Una comprobación rápida de solo lectura de que la impresora está lista para empezar a imprimir.`}},refresh:{t:0,b:{t:2,i:[{t:3}],s:`Volver a comprobar`}},checking:{t:0,b:{t:2,i:[{t:3}],s:`Comprobando...`}},ready:{t:0,b:{t:2,i:[{t:3}],s:`Lista para imprimir`}},notReady:{t:0,b:{t:2,i:[{t:3}],s:`No está lista para imprimir`}},checks:{unreachable:{fail:{t:0,b:{t:2,i:[{t:3}],s:`No se puede contactar con la impresora`}}},klippy:{pass:{t:0,b:{t:2,i:[{t:3}],s:`Klipper está listo`}},fail:{t:0,b:{t:2,i:[{t:3,v:`Klipper no está listo (estado: `},{t:4,k:`state`},{t:3,v:`)`}]}}},idle:{pass:{t:0,b:{t:2,i:[{t:3}],s:`No hay ninguna impresión en curso`}},fail:{t:0,b:{t:2,i:[{t:3,v:`Ya hay una impresión en ejecución (`},{t:4,k:`state`},{t:3,v:`)`}]}}},homed:{pass:{t:0,b:{t:2,i:[{t:3}],s:`Todos los ejes están en home`}},fail:{t:0,b:{t:2,i:[{t:3,v:`Ejes sin home (`},{t:4,k:`axes`},{t:3,v:`); al iniciar una impresión normalmente se hace home primero`}]}}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`Guía`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`Guía de comprobación previa a la impresión`}},close:{t:0,b:{t:2,i:[{t:3}],s:`Cerrar`}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:`¿Qué es la comprobación previa a la impresión?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Un vistazo de solo lectura de si la impresora está lista para empezar: nunca mueve ni cambia nada, solo informa. Los bloqueos graves ponen el veredicto en rojo; las advertencias informan pero no bloquean.`}}},checks:{title:{t:0,b:{t:2,i:[{t:3}],s:`Qué comprueba`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Que Klipper esté listo (no apagado ni en error), que no haya ya una impresión en ejecución y si los ejes están en home (informativo, ya que al iniciar una impresión normalmente se hace home primero).`}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`Glosario`}}}},glossary:{klippyState:{term:{t:0,b:{t:2,i:[{t:3}],s:`Estado de Klipper`}},def:{t:0,b:{t:2,i:[{t:3}],s:`El estado propio de Klipper - 'ready' (listo) significa que está conectado e inactivo; 'shutdown' (apagado) o 'error' significa que no puede imprimir hasta que se resuelva.`}}},homing:{term:{t:0,b:{t:2,i:[{t:3}],s:`Homing`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Mover cada eje hasta su endstop para que la impresora sepa dónde está el cabezal. La mayoría de las rutinas de inicio de impresión hacen home automáticamente.`}}}}}}};export{e as default};